/// <summary>
/// Override to show GUP UI only for vendor rebates when attribute based pricing is enabled
/// </summary>
/// <param name = "_formRun">Form object</param>
/// <param name = "_custVendValue">Module of the rebate</param>
/// <param name = "_useDirectValue">Should use directives or not</param>
/// <returns></returns>
public static boolean shouldShowGUPUI(FormRun _formRun, ModuleInventCustVend _custVendValue, boolean _useDirectValue)
{
    boolean showGUPUI = next shouldShowGUPUI(_formRun, _custVendValue, _useDirectValue);

    if (_useDirectValue)
    {
        showGUPUI = GUPGlobalEnableFeatureHelper::useAttributeBasedPricing()
                    && (_custVendValue == ModuleInventCustVend::Cust
                    || _custVendValue == ModuleInventCustVend::Vend);//Added Vend for CB705_VendorRebate
    }
    else
    {
        FormDataSource TAMRebateDeal_ds = _formRun.dataSource(tablestr(TAMRebateDeal));
        TAMRebateDeal  rebateDeal = TAMRebateDeal_ds.cursor();
        showGUPUI = GUPRebateMatchingHelper::isGUPCustomerRebate(rebateDeal);
    }

    return showGUPUI;
}

/// <summary>
/// Set the visibility of controls on the Rebate Deal Detail page for Vendor rebates
/// Bug 297355: CB234 - Vendor 1006495 - Price attribute detail - not showing ALL ITEMS when no attribute selected
/// </summary>
/// <param name = "_formRun">FormRun</param>
public static void setUpGUPUIForRebateDealFormDetailPage(FormRun _formRun)
{
    next setUpGUPUIForRebateDealFormDetailPage(_formRun);

    FormDataSource tamRebateDeal_ds = _formRun.dataSource(tablestr(TAMRebateDeal));
    TAMRebateDeal  rebateDeal = tamRebateDeal_ds.cursor();

    if (rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend)
    {
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PriceComponentCombination)).visible(false);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PricingAttributeGroupNameHeader)).visible(false);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PricingAttributeDetailsHeader)).visible(false);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PricingAttributeGroupNameLine)).visible(false);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PricingAttributeDetailsLine)).visible(false);
    }

}

/// <summary>
/// Bug 295616: CB234 - Price Attribute Details not displaying correctly on the line
/// Copy from std method to add another condition in the if statement
/// </summary>
/// <param name = "_formRun"><c>FormRun</c></param>
public static void setUpGUPUIForRebateDealNewDealForm(FormRun _formRun)
{
    next setUpGUPUIForRebateDealNewDealForm(_formRun);

    ModuleInventCustVend custVendValue;
    custVendValue = str2Enum(custVendValue, _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_ModuleInventCustVend)).valueStr());
    boolean showGUPUI = TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(_formRun, custVendValue, true);
    FormDataSource TAMRebateDeal_ds = _formRun.dataSource(tablestr(TAMRebateDeal));
    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, IsAttributeBasedRebate)).setValue(showGUPUI);
    TAMRebateType rebateType;
    rebateType = str2Enum(rebateType, _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateType)).valueStr());
    _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateTypeGUP)).visible(custVendValue == ModuleInventCustVend::Cust && rebateType == TAMRebateType::Rebate);

    // showGUPUI is now true for vendors as well
    if (showGUPUI)
    {
        TAMRebateReconciliation rebateReconciliation;
        rebateReconciliation = str2Enum(rebateReconciliation, _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateReconciliation)).valueStr());
        boolean currentRebateReconciliationIsDeal = rebateReconciliation == TAMRebateReconciliation::Deal;

        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateFromDate)).visible(true);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateFromDate)).allowEdit(currentRebateReconciliationIsDeal);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateFromDate)).mandatory(currentRebateReconciliationIsDeal);

        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebatePostingId)).allowEdit(true);

        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateToDate)).visible(true);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateToDate)).allowEdit(currentRebateReconciliationIsDeal);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateToDate)).mandatory(currentRebateReconciliationIsDeal);

        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateAgreementType)).visible(true);
        // Hide recipient for vendor only
        //_formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_Recipient)).visible(true);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_Recipient)).visible(custVendValue == ModuleInventCustVend::Cust);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateCompanyId)).visible(true);

        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateMatchedByOrderAccount)).visible(false);

        // Added for vendor
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateAgreementType)).mandatory(custVendValue == ModuleInventCustVend::Vend);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateCompanyId)).mandatory(custVendValue == ModuleInventCustVend::Vend);
    }
    else
    {
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateFromDate)).visible(false);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateFromDate)).mandatory(false);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateToDate)).visible(false);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateToDate)).mandatory(false);

        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateAgreementType)).mandatory(false);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateAgreementType)).visible(false);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_Recipient)).visible(false);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateCompanyId)).visible(true);
        // feature is internal, updating the code
        //_formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateMatchedByOrderAccount)).visible(TAMRebateMatchedByOrderAccountFeature::instance().isEnabled());
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateMatchedByOrderAccount)).visible(isFlightEnabled('TAMRebateMatchedByOrderAccountFeature'));

        TAMRebateDeal  rebateDeal = TAMRebateDeal_ds.cursor();
        rebateDeal.RebatePostingId = '';
    }


}
